610|632: function discoverExtensionsInDir(dir) {
611|633:     if (!fs.existsSync(dir)) {
612|634:         return [];
613|635:     }
614|636:     const discovered = [];
615|637:     try {
616|638:         const entries = fs.readdirSync(dir, { withFileTypes: true });
617|639:         for (const entry of entries) {
618|640:             const entryPath = path.join(dir, entry.name);
619|641:             // 1. Direct files: *.ts or *.js
620|642:             if ((entry.isFile() || entry.isSymbolicLink()) && isExtensionFile(entry.name)) {
621|643:                 discovered.push(entryPath);
622|644:                 continue;
623|645:             }
624|646:             // 2 & 3. Subdirectories
625|647:             if (entry.isDirectory() || entry.isSymbolicLink()) {
626|648:                 const entries = resolveExtensionEntries(entryPath);
627|649:                 if (entries) {
628|650:                     discovered.push(...entries);
629|651:                 }
630|652:             }
631|653:         }
632|654:     }
633|655:     catch {
634|656:         return [];
635|657:     }
636|658:     return discovered;
637|659: }
