646|668:     const addPaths = (paths) => {
647|669:         for (const p of paths) {
648|670:             const resolved = path.resolve(p);
649|671:             if (!seen.has(resolved)) {
650|672:                 seen.add(resolved);
651|673:                 allPaths.push(p);
652|674:             }
653|675:         }
654|676:     };
