25|  }
26|
27|  return new Promise((resolve) => {
28|    let done = false;
29|    let timeout: ReturnType<typeof setTimeout> | undefined;
30|    const finish = (delivered: boolean) => {
31|      if (done) return;
32|      done = true;
33|      if (timeout) {
34|        clearTimeout(timeout);
35|      }
36|      socket.destroy();
37|      resolve(delivered);
38|    };
39|
40|    const socket = net.createConnection(socketEndpoint!);
41|    socket.on("error", () => finish(false));
42|    socket.on("connect", () => socket.write(`${JSON.stringify(request)}\n`));
43|    socket.on("data", () => finish(true));
44|    socket.on("end", () => finish(false));
45|    timeout = setTimeout(() => finish(false), timeoutMs);
46|    timeout.unref?.();
