75|  try {
76|    const file = ctx?.sessionManager?.getSessionFile?.();
77|    currentAgentSessionPath =
78|      typeof file === "string" &&
79|      (path.posix.isAbsolute(file) || path.win32.isAbsolute(file))
80|        ? file
81|        : undefined;
82|  } catch {
83|    currentAgentSessionPath = undefined;
84|  }
85|
