94|function withSessionRef(params: Record<string, unknown>): Record<string, unknown> {
95|  if (currentAgentSessionPath) {
96|    return { ...params, agent_session_path: currentAgentSessionPath };
97|  }
98|  if (currentAgentSessionId) {
