104|function currentSessionRef(): Record<string, unknown> | undefined {
105|  if (currentAgentSessionPath) {
106|    return { agent_session_path: currentAgentSessionPath };
107|  }
108|  if (currentAgentSessionId) {
109|    return { agent_session_id: currentAgentSessionId };
110|  }
111|  return undefined;
112|}
113|
114|function reportSession(sessionStartSource?: string): Promise<void> {
115|  const sessionRef = currentSessionRef();
116|  if (!sessionRef) {
117|    return Promise.resolve();
118|  }
119|
120|  return sendRequest({
121|    id: `${source}:session:${Date.now()}:${Math.random().toString(36).slice(2)}`,
122|    method: "pane.report_agent_session",
123|    params: {
124|      pane_id: paneId,
125|      source,
126|      agent: "pi",
127|      seq: nextReportSeq(),
128|      session_start_source: sessionStartSource,
129|      ...sessionRef,
130|    },
131|  });
132|}
133|
134|function sendState(state: AgentState, message?: string, seq = nextReportSeq()): Promise<void> {
135|  return sendRequest({
136|    id: `${source}:${Date.now()}:${Math.random().toString(36).slice(2)}`,
137|    method: "pane.report_agent",
138|    params: withSessionRef({
139|      pane_id: paneId,
140|      source,
141|      agent: "pi",
142|      state,
143|      message,
144|      seq,
145|    }),
146|  });
147|}
148|
149|let sendInFlight = false;
150|let queuedState: QueuedState | undefined;
151|
152|function queueState(state: AgentState, message?: string): void {
153|  queuedState = { state, message, seq: nextReportSeq() };
154|  if (!sendInFlight) {
155|    void drainStateQueue();
156|  }
157|}
