159|async function drainStateQueue(): Promise<void> {
160|  if (sendInFlight) {
161|    return;
162|  }
163|
164|  sendInFlight = true;
165|  try {
166|    while (queuedState) {
167|      const next = queuedState;
168|      queuedState = undefined;
169|      await sendState(next.state, next.message, next.seq);
170|    }
171|  } finally {
172|    sendInFlight = false;
173|    if (queuedState) {
