54|let inFlight = 0;
55|const waiters = [];
56|
57|// The parsed reply, or null on any transport failure. A reply with an
58|// `error` field is still returned — the caller decides what a refusal means.
59|async function call(method, params) {
60|  if (inFlight >= MAX_IN_FLIGHT) await new Promise((wake) => waiters.push(wake));
61|  inFlight += 1;
62|  try {
63|    return await rawCall(method, params);
64|  } finally {
65|    inFlight -= 1;
66|    waiters.shift()?.();
67|  }
