3|// The daemon's frame scheduler: one timer, aimed at the earliest thing that
4|// needs doing. Wakes (events, file changes, the heartbeat) pull it closer; a
5|// finished frame pushes it out to the next real deadline; a floor keeps our
6|// own token writes, which echo back as events, from scheduling frames forever.
7|//
8|// Every interval here is measured on a monotonic clock, never the wall clock.
9|// The floor used to compare `Date.now()` against the time of the last frame,
10|// and a wall clock stepped BACKWARDS — NTP correcting a fast RTC at boot, which
11|// is when this daemon starts — makes that difference negative: every wake then
12|// looks too soon after the last frame, is pushed out to a "last frame + 150ms"
13|// that now lies minutes in the future, and the panel stops drawing for as long
14|// as the step was, while the process answers pings and looks healthy. Reported
15|// in #18.
16|//
17|// Callers hand this DELAYS, not moments. The frame's own deadlines are wall
18|// clock times — they are compared with persisted activity stamps, which must
19|// stay wall clock — so they are turned into a delay at the call site, in the
20|// same instant the wall clock was read, and no step can fall in between.
21|
22|function createScheduler({
23|  run,
24|  floorMs,
25|  pollMs,
26|  debounceMs,
27|  clock = () => performance.now(),
28|  setTimer = setTimeout,
29|  clearTimer = clearTimeout,
30|}) {
31|  let timer = null;
32|  let nextAt = Infinity;
33|  let running = false;
34|  let rerun = false;
35|  let lastFrameAt = -Infinity;
36|  const bornAt = clock();
37|  let lastFireAt = bornAt;
38|
39|  const scheduleIn = (ms) => {
40|    const at = clock() + Math.max(0, ms);
41|    if (timer && at >= nextAt) return;
42|    if (timer) clearTimer(timer);
43|    nextAt = at;
44|    timer = setTimer(fire, Math.max(0, at - clock()));
45|  };
46|
47|  const wake = () => scheduleIn(debounceMs);
48|
49|  async function fire() {
50|    timer = null;
51|    nextAt = Infinity;
52|    lastFireAt = clock();
53|    if (running) {
54|      rerun = true;
55|      return;
56|    }
57|    const since = clock() - lastFrameAt;
58|    if (since < floorMs) {
59|      scheduleIn(pollMs - since);
60|      return;
61|    }
62|    running = true;
63|    lastFrameAt = clock();
64|    try {
65|      await run();
66|    } finally {
67|      running = false;
68|      if (rerun) {
69|        rerun = false;
70|        wake();
71|      }
72|    }
73|  }
74|
75|  return {
76|    wake,
77|    scheduleIn,
78|    isRunning: () => running,
79|    // Two different ways of not drawing, reported separately on `ping` so the
80|    // watchdog can judge each on its own clock (lib/state.js daemonStatus).
81|    //
82|    // `fireAgeMs`: how long since the timer last fired at all. The heartbeat
83|    // fires it every two seconds whatever else is going on — even while a
84|    // frame is in flight, where it only notes a rerun — so a gap here means
85|    // the timers themselves have stopped.
86|    //
87|    // `runningForMs`: how long the frame in flight has been running, zero
88|    // when none is. A frame waits on IPC calls that each time out in seconds,
89|    // so a long one is a slow Herdr, not a stall, until it is very long.
90|    fireAgeMs: () => clock() - lastFireAt,
91|    runningForMs: () => (running ? clock() - lastFrameAt : 0),
92|  };
93|}
